"  const requestPasscodeAuthorization = (permissionKey, onApproved, onDenied = null, forcePasscode = false) => {
    const access = getStaffPermissions()?.pos_access;
    let isAllowedDirectly = false;
    let isPasscodeRequired = forcePasscode;

    if (!forcePasscode) {
      if (permissionKey === 'add_discount') {
        isAllowedDirectly = checkBillingPermission('add_discount');
        isPasscodeRequired = access?.Billing?.add_discount_passcode === true;
      } else if (permissionKey === 'add_coupon') {
        isAllowedDirectly = checkBillingPermission('add_coupon');
        isPasscodeRequired = access?.Billing?.add_coupon_passcode === true;
      } else if (permissionKey === 'add_charges') {
        isAllowedDirectly = checkBillingPermission('add_charges');
        isPasscodeRequired = access?.Billing?.add_charges_passcode === true;
      } else if (permissionKey === 'allowed_due_payment') {
        isAllowedDirectly = checkBillingPermission('allowed_due_payment');
        isPasscodeRequired = access?.Billing?.allowed_due_payment_passcode === true;
      } else {
        isAllowedDirectly = true;
      }
    }

    if (isAllowedDirectly && !isPasscodeRequired) {
      onApproved();
      return;
    }

    setPasscodeAction({
      permissionKey,
      onApproved,
      onDenied
    });
    setPasscodeValue('');
    setPasscodeError('');
    setIsPasscodeModalOpen(true);
  };"

